mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.member member,
  ttokssaemdb.checkvocaplan vocatest

  AND member.memberid = vocatest.memberid

    AND member.branchid = #{branchid}


    AND vocatest.memodate = #{memodate}


    AND (
      member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT member.memberid, member.membername, vocatest.id, vocatest.memodate, vocatest.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocatest.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocatest.vocano, vocatest.targetcount, vocatest.lastyn, vocatest.examflag, (SELECT stopyn FROM ttokssaemdb.vocaplan WHERE memberid = vocatest.memberid) stopyn, IFNULL(vocaexam.degree, 0) degree, IFNULL((SELECT total FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) total, IFNULL((SELECT wrong FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) wrong FROM ttokssaemdb.member member, ttokssaemdb.checkvocaplan vocatest LEFT JOIN ( SELECT memberid, MAX(degree) degree FROM ttokssaemdb.vocaexam WHERE memodate = #{memodate} GROUP BY memberid ) vocaexam ON vocatest.memberid = vocaexam.memberid
AND member.memberid = vocatest.memberid
AND vocatest.memodate = #{memodate}
AND member.branchid = #{branchid}
AND ( member.membername LIKE #{likeQuery} )
vocatest.id vocatest.vocalevel vocatest.vocalevel vocatest.vocano vocatest.memodate vocatest.lastyn vocatest.examflag member.membername DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

mapper.delete:
DELETE FROM ttokssaemdb.checkvocaplan
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

DELETE FROM ttokssaemdb.vocamemo
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

mapper.update:
UPDATE ttokssaemdb.checkvocaplan
  SET
    examflag = 'C'
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

UPDATE ttokssaemdb.vocasolve
  SET
    result = #{result}
WHERE
  id = #{id}

UPDATE ttokssaemdb.vocaexam
SET
  result = #{finishflag},
  total = ${total},
  wrong = ${wrong},
  findate = now()
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}
  AND degree = #{degree}

UPDATE ttokssaemdb.checkvocaplan
SET
  examflag = #{finishflag}
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}
